-- Stage 17: additive, fail-closed, two-call listing review. No keys, live
-- qualification, provider requests, account changes, or activation are installed.
create table public.listing_runs (
 id uuid primary key, business_id uuid not null references public.businesses(id) on delete restrict,
 owner_id uuid not null references auth.users(id) on delete restrict,
 workflow_run_id uuid not null unique, source_artifact_id uuid not null, output_artifact_id uuid not null unique,
 input jsonb not null check(jsonb_typeof(input)='object'), input_hash text not null check(input_hash ~ '^[a-f0-9]{64}$'),
 source_content_hash text not null check(source_content_hash ~ '^[a-f0-9]{64}$'),
 knowledge_hash text not null check(knowledge_hash ~ '^[a-f0-9]{64}$'), worker_hashes jsonb not null,
 catalog_snapshot jsonb not null, quote jsonb not null,
 maximum_microusd bigint not null check(maximum_microusd between 1 and 1000000),
 capability_expires_at timestamptz not null, created_at timestamptz not null default now(),
 status text not null default 'queued' check(status in ('queued','running','completed','rejected','needs_evidence','failed','cancelled')),
 phase text not null default 'specialist' check(phase in ('specialist','reviewer','issue','terminal')),
 reason text, completed_at timestamptz,
 foreign key(workflow_run_id,business_id) references public.workflow_runs(id,business_id) on delete restrict,
 foreign key(source_artifact_id,business_id) references public.artifacts(id,business_id) on delete restrict,
 unique(business_id,source_artifact_id,input_hash), unique(id,business_id), unique(id,workflow_run_id,business_id)
);
create table private.listing_run_capabilities (
 listing_run_id uuid primary key references public.listing_runs(id) on delete restrict,
 capability_hash text not null check(capability_hash ~ '^[a-f0-9]{64}$'), launch_nonce uuid not null
);
-- A private transaction-scoped admission record prevents older generic SECURITY
-- DEFINER RPCs from mutating Listing Core state, even if they run as postgres.
create table private.listing_mutation_admissions (transaction_id bigint primary key);
-- Empty until a separately reviewed trusted qualification procedure is approved.
-- Owner-controlled Stage6 evidence alone is never a live execution authority.
create table private.listing_live_qualifications (
 id uuid primary key default gen_random_uuid(), worker_definition_id uuid not null references public.worker_definitions(id) on delete restrict,
 evaluation_id uuid not null references public.worker_evaluations(id) on delete restrict,
 worker_fingerprint text not null check(worker_fingerprint ~ '^[a-f0-9]{64}$'), knowledge_hash text not null check(knowledge_hash ~ '^[a-f0-9]{64}$'),
 model_id text not null check(model_id in ('openai/gpt-5.6-luna','anthropic/claude-haiku-4.5')),
 qualification_scope text not null check(qualification_scope='stage17_listing_review'), evidence jsonb not null check(jsonb_typeof(evidence)='object'),
 qualified_at timestamptz not null, expires_at timestamptz not null,
 check(expires_at>qualified_at and expires_at<=qualified_at+interval '30 days'), unique(worker_definition_id,evaluation_id,worker_fingerprint,knowledge_hash)
);
create function private.stage17_qualification_immutable() returns trigger language plpgsql set search_path='' as $$ begin
 if current_user in ('anon','authenticated','service_role') or tg_op<>'INSERT' then raise exception 'listing_live_qualification_trusted_only' using errcode='42501'; end if;
 return new;
end $$;
create trigger listing_live_qualification_immutable before insert or update or delete on private.listing_live_qualifications for each row execute function private.stage17_qualification_immutable();

create table public.listing_cost_reservations (
 listing_run_id uuid not null, business_id uuid not null, role text not null check(role in ('specialist','reviewer')),
 reserved_microusd bigint not null check(reserved_microusd between 0 and 1000000),
 request_hash text not null check(request_hash ~ '^[a-f0-9]{64}$'), model text not null,
 provider text not null check(provider='openrouter'), estimate jsonb not null, context jsonb not null,
 task_contract_id uuid not null, worker_run_id uuid not null,
 created_at timestamptz not null default now(), primary key(listing_run_id,role),
 foreign key(listing_run_id,business_id) references public.listing_runs(id,business_id) on delete restrict,
 foreign key(task_contract_id,business_id) references public.task_contracts(id,business_id) on delete restrict,
 foreign key(worker_run_id,business_id) references public.worker_runs(id,business_id) on delete restrict,
 unique(listing_run_id,role,business_id), unique(task_contract_id), unique(worker_run_id)
);
create table public.listing_cost_settlements (
 listing_run_id uuid not null, business_id uuid not null, role text not null,
 reported_microusd bigint check(reported_microusd between 0 and 9007199254740991),
 provider_request_id text check(length(provider_request_id) between 1 and 300),
 receipt jsonb not null check(jsonb_typeof(receipt)='object'), created_at timestamptz not null default now(),
 primary key(listing_run_id,role),
 foreign key(listing_run_id,role,business_id) references public.listing_cost_reservations(listing_run_id,role,business_id) on delete restrict
);
create table public.listing_phase_outputs (
 listing_run_id uuid not null, business_id uuid not null, workflow_run_id uuid not null, role text not null,
 artifact_id uuid not null, output jsonb not null check(jsonb_typeof(output)='object'),
 output_hash text not null check(output_hash ~ '^[a-f0-9]{64}$'), execution jsonb not null,
 created_at timestamptz not null default now(), primary key(listing_run_id,role),
 foreign key(listing_run_id,workflow_run_id,business_id) references public.listing_runs(id,workflow_run_id,business_id) on delete restrict,
 foreign key(listing_run_id,role,business_id) references public.listing_cost_reservations(listing_run_id,role,business_id) on delete restrict,
 foreign key(artifact_id,workflow_run_id,business_id) references public.artifacts(id,workflow_run_id,business_id) on delete restrict
);
create function private.stage17_admitted() returns boolean language sql stable set search_path='' as $$
 select current_user not in ('anon','authenticated','service_role') and exists(select 1 from private.listing_mutation_admissions where transaction_id=txid_current());
$$;
create function private.stage17_record_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if not private.stage17_admitted() then raise exception 'listing_runtime_managed' using errcode='42501'; end if;
 if tg_table_name='listing_runs' then
  if tg_op='DELETE' then raise exception 'listing_history_immutable'; end if;
  if tg_op='UPDATE' and to_jsonb(new)-array['status','phase','reason','completed_at'] is distinct from to_jsonb(old)-array['status','phase','reason','completed_at'] then raise exception 'listing_identity_immutable'; end if;
  if tg_op='UPDATE' and old.status in ('completed','rejected','needs_evidence','failed','cancelled') and new is distinct from old then raise exception 'listing_terminal_immutable'; end if;
 elsif tg_op<>'INSERT' then raise exception 'listing_provenance_append_only'; end if;
 return new;
end $$;
do $$ declare n text; begin
 foreach n in array array['listing_runs','listing_cost_reservations','listing_cost_settlements','listing_phase_outputs'] loop
  execute format('alter table public.%I enable row level security',n);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',n);
  execute format('grant select on public.%I to authenticated',n);
  execute format('create policy %I on public.%I for select to authenticated using(private.is_business_owner(business_id))',n||'_owner_read',n);
  execute format('create trigger %I before insert or update or delete on public.%I for each row execute function private.stage17_record_guard()',n||'_guard',n);
  execute format('create index %I on public.%I(business_id)',n||'_business',n);
 end loop;
 foreach n in array array['listing_run_capabilities','listing_mutation_admissions','listing_live_qualifications'] loop
  execute format('alter table private.%I enable row level security',n);
  execute format('revoke all on private.%I from public,anon,authenticated,service_role',n);
 end loop;
end $$;
create trigger listing_capability_immutable before insert or update or delete on private.listing_run_capabilities for each row execute function private.stage17_record_guard();

create function private.stage17_core_guard() returns trigger language plpgsql set search_path='' as $$
declare a jsonb; b jsonb; protected boolean:=false; v uuid;
begin
 if tg_op<>'INSERT' then a:=to_jsonb(old); end if;
 if tg_op<>'DELETE' then b:=to_jsonb(new); end if;
 if tg_table_name='artifacts' and (coalesce(a->>'artifact_type','') in ('product.package.v1','listing.business-facts.v1','listing.image-review.v1','listing.input.v1','listing.specialist.v1','listing.reviewer.v1') or coalesce(b->>'artifact_type','') in ('product.package.v1','listing.business-facts.v1','listing.image-review.v1','listing.input.v1','listing.specialist.v1','listing.reviewer.v1') or a->'content' ?| array['listingInputEnvelope','listingReviewEnvelope','imageReviewEnvelope','listingSourceEnvelope'] or b->'content' ?| array['listingInputEnvelope','listingReviewEnvelope','imageReviewEnvelope','listingSourceEnvelope']) then
  if current_user in ('anon','authenticated','service_role') then raise exception 'listing_source_is_server_managed' using errcode='42501'; end if;
  if tg_op<>'INSERT' then raise exception 'listing_source_immutable'; end if;
 end if;
 if tg_table_name='workflow_runs' then
  protected:=exists(select 1 from public.workflow_definitions where workflow_key in ('etsy.listing-review','etsy.listing-qualification') and id in ((a->>'workflow_definition_id')::uuid,(b->>'workflow_definition_id')::uuid));
  if tg_op='UPDATE' and protected and a-array['status','current_stage_key','state','started_at','completed_at','updated_at','runtime_run_id','runtime_launch_status','runtime_launch_reserved_at'] is distinct from b-array['status','current_stage_key','state','started_at','completed_at','updated_at','runtime_run_id','runtime_launch_status','runtime_launch_reserved_at'] then raise exception 'listing_core_identity_immutable'; end if;
 else
  for v in select distinct x from unnest(array[(a->>'workflow_run_id')::uuid,(b->>'workflow_run_id')::uuid]) x where x is not null loop
   protected:=protected or exists(select 1 from public.workflow_runs w join public.workflow_definitions d on d.id=w.workflow_definition_id where w.id=v and d.workflow_key in ('etsy.listing-review','etsy.listing-qualification'));
  end loop;
 end if;
 if protected then
  if not private.stage17_admitted() then raise exception 'listing_core_runtime_managed' using errcode='42501'; end if;
  if tg_op='DELETE' or (tg_table_name in ('artifacts','events') and tg_op<>'INSERT') then raise exception 'listing_core_provenance_immutable'; end if;
 end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $$;
do $$ declare n text; begin
 foreach n in array array['workflow_runs','workflow_stage_runs','task_contracts','worker_runs','artifacts','events','owner_interventions','action_intents'] loop
  execute format('create trigger %I before insert or update or delete on public.%I for each row execute function private.stage17_core_guard()','stage17_'||n||'_guard',n);
 end loop;
end $$;

create function private.stage17_costs(p_run uuid) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('knownMicrousd',coalesce(sum(s.reported_microusd),0),'reservedMicrousd',coalesce(sum(r.reserved_microusd),0),
 'committedMicrousd',coalesce(sum(coalesce(s.reported_microusd,r.reserved_microusd)),0),
 'unknownCount',count(*) filter(where s.listing_run_id is not null and s.reported_microusd is null),'pendingCount',count(*) filter(where s.listing_run_id is null))
 from public.listing_cost_reservations r left join public.listing_cost_settlements s using(listing_run_id,role,business_id) where r.listing_run_id=p_run;
$$;
create function private.stage17_assert_sources(p_business uuid,p_source uuid,p_content_hash text,p_input jsonb,p_input_hash text) returns void language plpgsql set search_path='' as $$
declare a public.artifacts%rowtype; s jsonb; actual jsonb; proof jsonb; image jsonb; approval public.creative_approvals%rowtype; verified timestamptz;
begin
 select * into strict a from public.artifacts where id=p_source and business_id=p_business and artifact_type='product.package.v1';
 if a.content->>'listingInputEnvelope' is null or length(a.content->>'listingInputEnvelope')<32 or a.content->'listingInput' is distinct from p_input
  or private.stage14_hash(a.content) is distinct from p_content_hash or private.stage14_hash(p_input) is distinct from p_input_hash
  or p_input->>'version' is distinct from '1.0.0' or p_input->>'evidenceMode' is distinct from 'live'
  or p_input->'product'->>'id' is distinct from p_source::text or p_input->'product'->>'businessId' is distinct from p_business::text
  then raise exception 'listing_source_input_mismatch'; end if;
 perform private.stage16_assert_package(p_business,p_input->'product');
 verified:=(p_input->>'factsVerifiedAt')::timestamptz;
 if verified is null or verified>clock_timestamp() or verified<=clock_timestamp()-interval '1 day' then raise exception 'listing_facts_stale'; end if;
 if jsonb_typeof(p_input->'sources') is distinct from 'array' or jsonb_array_length(p_input->'sources') not between 1 and 12 or
  (select count(*)<>count(distinct x->>'id') from jsonb_array_elements(p_input->'sources') x) then raise exception 'listing_sources_required'; end if;
 if not exists(select 1 from jsonb_array_elements(p_input->'sources') as check_source(v) where check_source.v->>'recordType'='printful_receipt') then raise exception 'listing_printful_readback_required'; end if;
 for s in select value from jsonb_array_elements(p_input->'sources') loop
  actual:=null; verified:=(s->>'verifiedAt')::timestamptz;
  if s->>'businessId' is distinct from p_business::text or private.stage14_hash(s->'snapshot') is distinct from s->>'snapshotHash' or verified is null or verified>clock_timestamp() or verified<=clock_timestamp()-interval '1 day' then raise exception 'listing_source_snapshot_invalid'; end if;
  if s->>'recordType'='printful_receipt' then
   if s->>'recordId' is distinct from p_input->'product'->>'printfulReceiptId' then raise exception 'listing_receipt_binding_invalid'; end if;
   select response_summary->'listingFacts' into actual from public.action_receipts where id=(s->>'recordId')::uuid and business_id=p_business and provider='printful' and outcome='succeeded';
  elsif s->>'recordType'='creative_approval' then
   if s->>'recordId' is distinct from p_input->'product'->>'creativeApprovalId' then raise exception 'listing_approval_binding_invalid'; end if;
   select * into strict approval from public.creative_approvals where id=(s->>'recordId')::uuid and business_id=p_business;
   select jsonb_object_agg(key,value) into actual from jsonb_each(approval.snapshot) where key=any(array['concept','designInstructions','rightsStatement','rightsConfirmed','originalDesign']);
  elsif s->>'recordType'='business_approval' then
   select content->'listingSourceSnapshot' into actual from public.artifacts where id=(s->>'recordId')::uuid and business_id=p_business and artifact_type='listing.business-facts.v1' and length(content->>'listingSourceEnvelope')>=32;
  else raise exception 'listing_source_type_invalid'; end if;
  if actual is null or actual is distinct from s->'snapshot' then raise exception 'listing_source_record_mismatch'; end if;
 end loop;
 if p_input->'aiAssisted' is distinct from to_jsonb(exists(select 1 from public.creative_assets where business_id=p_business and creative_run_id=(p_input->'product'->>'creativeRunId')::uuid)) then raise exception 'listing_ai_provenance_mismatch'; end if;
 if jsonb_typeof(p_input->'imagery') is distinct from 'array' or jsonb_array_length(p_input->'imagery')<>jsonb_array_length(p_input->'product'->'images') then raise exception 'listing_image_proof_required'; end if;
 for image in select value from jsonb_array_elements(p_input->'product'->'images') loop
  if (select count(*) from jsonb_array_elements(p_input->'imagery') x where x->>'assetId'=image->>'assetId')<>1 then raise exception 'listing_image_proof_required'; end if;
  select value into strict proof from jsonb_array_elements(p_input->'imagery') x where x->>'assetId'=image->>'assetId';
  select content->'proof' into actual from public.artifacts where id=(proof->>'reviewArtifactId')::uuid and business_id=p_business and artifact_type='listing.image-review.v1' and content->>'reviewResultHash'=proof->>'reviewResultHash' and length(content->>'imageReviewEnvelope')>=32;
  if actual is null or actual is distinct from proof or private.stage14_hash(proof-'reviewResultHash') is distinct from proof->>'reviewResultHash'
   or proof->>'sha256' is distinct from image->>'sha256' or proof->>'altText' is distinct from image->>'altText' or proof->>'productFactsHash' is distinct from p_input->'product'->>'productFactsHash'
   or proof->'finishedProductShown' is distinct from 'true'::jsonb or proof->'reviewResult'->>'outcome' is distinct from 'PASS'
   or proof->'reviewResult'->>'businessId' is distinct from p_business::text or proof->'reviewResult'->'productMatches' is distinct from 'true'::jsonb
   or proof->'reviewResult'->'finishedProductShown' is distinct from 'true'::jsonb or proof->'reviewResult'->'imageRightsVerified' is distinct from 'true'::jsonb
   or coalesce(length(btrim(proof->'reviewResult'->>'observedProduct')),0) not between 40 and 1000
   or coalesce(proof->>'kind','') not in ('finished_product_mockup','finished_product_photo')
   or (p_input->>'productType'='custom_manufactured' and proof->>'kind'<>'finished_product_photo')
   or coalesce((proof->>'reviewedAt')::timestamptz,'-infinity')<=clock_timestamp()-interval '1 day' or (proof->>'reviewedAt')::timestamptz>clock_timestamp()
   then raise exception 'listing_image_proof_mismatch'; end if;
 end loop;
end $$;

create function private.stage17_assert_catalog(p_knowledge_hash text,p_worker_hashes jsonb) returns jsonb language plpgsql set search_path='' as $$
declare role_name text; d public.worker_definitions%rowtype; p public.packs%rowtype; m jsonb; k jsonb; result jsonb:='{}'; expected_model text;
begin
 select p0.manifest->'knowledge'->0 into strict k from public.packs p0 join public.pack_knowledge_definitions kd on kd.pack_id=p0.id
  where p0.pack_key='knowledge.etsy-listing-review' and p0.version='1.0.0' and p0.status<>'retired' and kd.knowledge_key='etsy.listing-review' and kd.version='1.0.0'
   and kd.content=p0.manifest->'knowledge'->0->'content' and kd.verified_at=(p0.manifest->'knowledge'->0->>'verifiedAt')::timestamptz and kd.freshness_days=(p0.manifest->'knowledge'->0->>'freshnessDays')::integer;
 if private.stage14_hash(k) is distinct from p_knowledge_hash or (k->>'verifiedAt')::timestamptz>clock_timestamp() or (k->>'verifiedAt')::timestamptz+(k->>'freshnessDays')::integer*interval '1 day'<=clock_timestamp() then raise exception 'listing_knowledge_changed_or_stale'; end if;
 foreach role_name in array array['specialist','reviewer'] loop
  expected_model:=case role_name when 'specialist' then 'openai/gpt-5.6-luna' else 'anthropic/claude-haiku-4.5' end;
  select * into strict p from public.packs where pack_key='worker.listing-'||role_name and version='1.0.0' and status<>'retired';
  m:=p.manifest->'workers'->0->'manifest';
  select * into strict d from public.worker_definitions where pack_id=p.id and worker_key='listing.'||role_name and version='1.0.0';
  if private.stage14_hash(m) is distinct from p_worker_hashes->>role_name or d.input_schema is distinct from m->'inputSchema' or d.output_schema is distinct from m->'outputSchema'
   or d.model_requirements is distinct from m->'modelRequirements' or d.capability_requirements is distinct from m->'capabilityPolicy'->'allowed' or d.knowledge_requirements is distinct from m->'knowledgeRequirements'
   or d.charter is distinct from m->'worker'->>'charter' or d.role is distinct from m->'worker'->>'role'
   or m->'capabilityPolicy'->'allowed' is distinct from '[]'::jsonb or m->'modelRequirements'->'maximumAttempts' is distinct from '1'::jsonb
   or m->'modelRequirements'->'primaryOnly' is distinct from 'true'::jsonb or m->'modelRequirements'->>'qualificationScope' is distinct from 'stage17_listing_review'
   then raise exception 'listing_worker_source_changed'; end if;
  if not private.stage6_worker_is_currently_qualified(d.id) then raise exception 'listing_worker_not_currently_qualified'; end if;
  if not exists(select 1 from private.listing_live_qualifications q join public.worker_evaluations e on e.id=q.evaluation_id
   where q.worker_definition_id=d.id and e.worker_definition_id=d.id and e.status='passed' and e.subject_fingerprint=q.worker_fingerprint
    and q.worker_fingerprint=private.stage6_worker_fingerprint(d.id) and q.knowledge_hash=p_knowledge_hash and q.model_id=expected_model and q.qualification_scope='stage17_listing_review'
    and q.qualified_at<=clock_timestamp() and q.expires_at>clock_timestamp()
    and q.evidence->>'mode'='live_model' and q.evidence->'mockProvider'='false'::jsonb
    and jsonb_typeof(q.evidence->'providerRequestIds')='array' and jsonb_array_length(q.evidence->'providerRequestIds')>=2
    and (select count(*)=count(distinct value) from jsonb_array_elements_text(q.evidence->'providerRequestIds'))
    and not exists(select 1 from jsonb_array_elements_text(q.evidence->'providerRequestIds') x where length(btrim(x)) not between 1 and 300 or x ~ '^(synthetic:|simulation:|fixture:|mock:)')
    and private.stage17_qualification_attestation_current(q.id)
    and length(btrim(q.evidence->>'reviewSummary')) between 40 and 4000)
   then raise exception 'listing_trusted_live_qualification_required'; end if;

  if not exists(select 1 from public.model_routes route join public.model_definitions model on model.id=route.primary_model_definition_id
   where route.route_key=d.model_requirements->>'routeKey' and model.provider='openrouter' and model.provider_model_id=expected_model) then raise exception 'listing_primary_model_changed'; end if;
  result:=result||jsonb_build_object(role_name,jsonb_build_object('workerDefinitionId',d.id,'workerFingerprint',private.stage6_worker_fingerprint(d.id),'manifest',m,'pack',p.manifest));
 end loop;
 return result||jsonb_build_object('knowledge',k);
end $$;
create function private.stage17_assert_quote(p_quote jsonb,p_input_hash text,p_maximum bigint) returns void language plpgsql set search_path='' as $$
declare n text; amount bigint;
begin
 if jsonb_typeof(p_quote) is distinct from 'object' or p_quote->>'version' is distinct from 'listing-estimate-1.0' or p_quote->>'inputHash' is distinct from p_input_hash
  or p_quote->'maximumCalls' is distinct from '2'::jsonb or p_quote->'primaryOnly' is distinct from 'true'::jsonb or p_quote->'estimateOnly' is distinct from 'true'::jsonb or p_quote->'providerInvoiceGuarantee' is distinct from 'false'::jsonb
  or p_quote->>'source' is distinct from 'https://openrouter.ai/api/v1/models' or p_quote->'models' is distinct from '{"specialist":"openai/gpt-5.6-luna","reviewer":"anthropic/claude-haiku-4.5"}'::jsonb
  or coalesce((p_quote->>'verifiedAt')::timestamptz,'-infinity')<=clock_timestamp()-interval '5 minutes' or (p_quote->>'verifiedAt')::timestamptz>clock_timestamp()
  or p_maximum is null or p_maximum not between 1 and 1000000 then raise exception 'listing_quote_invalid_or_stale'; end if;
 foreach n in array array['specialist','reviewer'] loop
  if jsonb_typeof(p_quote->'ceilings'->n) is distinct from 'number' or (p_quote->'ceilings'->>n)::numeric<>trunc((p_quote->'ceilings'->>n)::numeric) then raise exception 'listing_quote_ceiling_invalid'; end if;
  amount:=(p_quote->'ceilings'->>n)::bigint;
  if amount not between 0 and p_maximum then raise exception 'listing_quote_ceiling_invalid'; end if;
 end loop;
 if jsonb_typeof(p_quote->'maximumEstimateMicrousd') is distinct from 'number' or (p_quote->>'maximumEstimateMicrousd')::numeric<>trunc((p_quote->>'maximumEstimateMicrousd')::numeric) or (p_quote->>'maximumEstimateMicrousd')::bigint is distinct from (p_quote->'ceilings'->>'specialist')::bigint+(p_quote->'ceilings'->>'reviewer')::bigint
  or (p_quote->>'maximumEstimateMicrousd')::bigint>p_maximum then raise exception 'listing_quote_exceeds_approval'; end if;
end $$;
create function private.stage17_close(p_run uuid,p_status text,p_reason text) returns void language plpgsql set search_path='' as $$
declare r public.listing_runs%rowtype;
begin
 select * into strict r from public.listing_runs where id=p_run for update;
 if r.status in ('completed','rejected','needs_evidence','failed','cancelled') then return; end if;
 if p_status not in ('completed','rejected','needs_evidence','failed','cancelled') then raise exception 'listing_terminal_status_invalid'; end if;
 update public.listing_runs set status=p_status,phase='terminal',reason=left(p_reason,1500),completed_at=clock_timestamp() where id=r.id;
 update public.workflow_runs set status=case when p_status in ('rejected','needs_evidence') then 'completed' else p_status end,current_stage_key='terminal',completed_at=clock_timestamp(),state=state||jsonb_build_object('reason',left(p_reason,1500),'publicationAllowed',false) where id=r.workflow_run_id;
 update public.workflow_stage_runs set status=case when status='running' then 'failed' else 'skipped' end,completed_at=clock_timestamp(),failure=jsonb_build_object('reason',left(p_reason,1500)) where workflow_run_id=r.workflow_run_id and status in ('pending','running');
 update public.task_contracts set status=case when p_status='cancelled' then 'cancelled' else 'failed' end where workflow_run_id=r.workflow_run_id and status in ('draft','ready','running');
 update public.worker_runs set status=case when p_status='cancelled' then 'cancelled' else 'failed' end,completed_at=clock_timestamp(),failure=jsonb_build_object('reason',left(p_reason,1500)) where workflow_run_id=r.workflow_run_id and status in ('queued','running');
 insert into public.events(business_id,workflow_run_id,event_type,actor_type,payload) values(r.business_id,r.workflow_run_id,'listing.'||p_status,'system',jsonb_build_object('listingRunId',r.id,'reason',left(p_reason,1500),'costs',private.stage17_costs(r.id),'publicationAllowed',false));
end $$;
create function private.stage17_view(p_run uuid) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('id',r.id,'businessId',r.business_id,'workflowRunId',r.workflow_run_id,'sourceArtifactId',r.source_artifact_id,'outputArtifactId',r.output_artifact_id,
 'input',r.input,'inputHash',r.input_hash,'sourceEnvelope',a.content->>'listingInputEnvelope','knowledgeHash',r.knowledge_hash,'workerHashes',r.worker_hashes,
 'status',r.status,'phase',r.phase,'reason',r.reason,'maximumMicrousd',r.maximum_microusd,'quote',r.quote,'costs',private.stage17_costs(r.id),
 'taskIds',jsonb_build_object('specialist',private.stage4_deterministic_uuid('listing:task:'||r.id||':specialist'),'reviewer',private.stage4_deterministic_uuid('listing:task:'||r.id||':reviewer')),
 'outputs',coalesce((select jsonb_object_agg(role,jsonb_build_object('output',output,'execution',execution)) from public.listing_phase_outputs where listing_run_id=r.id),'{}'::jsonb))
 from public.listing_runs r join public.artifacts a on a.id=r.source_artifact_id and a.business_id=r.business_id where r.id=p_run;
$$;
create function private.stage17_qualified() returns boolean language plpgsql set search_path='' as $$
declare k text; w jsonb;
begin
 select private.stage14_hash(manifest->'knowledge'->0) into k from public.packs where pack_key='knowledge.etsy-listing-review' and version='1.0.0';
 select jsonb_object_agg(replace(pack_key,'worker.listing-',''),private.stage14_hash(manifest->'workers'->0->'manifest')) into w from public.packs where pack_key in ('worker.listing-specialist','worker.listing-reviewer') and version='1.0.0';
 perform private.stage17_assert_catalog(k,w); return true;
 exception when others then return false;
end $$;
create function private.stage17_owner(p_business_id uuid,p_operation text,p_payload jsonb,p_server_key text) returns jsonb language plpgsql set search_path='' as $$
declare r public.listing_runs%rowtype; a public.artifacts%rowtype; catalog jsonb; workflow public.workflow_definitions%rowtype;
 run_id uuid:=gen_random_uuid(); workflow_id uuid:=gen_random_uuid(); output_id uuid:=gen_random_uuid(); role_name text; n integer:=0;
begin
 if p_operation in ('start_qualification','cancel_qualification','fail_qualification_launch') then return private.stage17_qualification_owner(p_business_id,p_operation,p_payload,p_server_key); end if;
 if p_operation='workspace' then
  return jsonb_build_object('qualificationRuns',private.stage17_qualification_owner(p_business_id,'qualification_workspace','{}'::jsonb,p_server_key)->'runs','qualified',private.stage17_qualified(),'authorityConfigured',coalesce(length(p_server_key)>=32 and exists(select 1 from private.etsy_server_authority where enabled and key_hash=private.stage13_hash(p_server_key)),false),'runs',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'workflowRunId',x.workflow_run_id,'sourceArtifactId',x.source_artifact_id,'outputArtifactId',x.output_artifact_id,'status',x.status,'phase',x.phase,'reason',x.reason,'maximumMicrousd',x.maximum_microusd,'costSummary',private.stage17_costs(x.id),'costs',coalesce((select jsonb_agg(jsonb_build_object('role',c.role,'reservedMicrousd',c.reserved_microusd,'reportedMicrousd',s.reported_microusd,'providerRequestId',s.provider_request_id,'settled',s.listing_run_id is not null) order by c.created_at) from public.listing_cost_reservations c left join public.listing_cost_settlements s using(listing_run_id,role,business_id) where c.listing_run_id=x.id),'[]'::jsonb),'approvedAt',x.created_at,'createdAt',x.created_at,'expiresAt',x.capability_expires_at,'proposal',(select output from public.listing_phase_outputs where listing_run_id=x.id and role='specialist'),'review',(select output from public.listing_phase_outputs where listing_run_id=x.id and role='reviewer')) order by x.created_at desc) from (select * from public.listing_runs where business_id=p_business_id order by created_at desc limit 50) x),'[]'::jsonb));
 end if;
 if p_operation='start' then
  if p_payload->'approveModelCalls' is distinct from 'true'::jsonb then raise exception 'listing_model_call_approval_required'; end if;
  if length(p_server_key)<32 or not exists(select 1 from private.etsy_server_authority where key_hash=private.stage13_hash(p_server_key) and enabled) then raise exception 'server_authority_required' using errcode='42501'; end if;
  if jsonb_typeof(p_payload->'maximumMicrousd') is distinct from 'number' or (p_payload->>'maximumMicrousd')::numeric<>trunc((p_payload->>'maximumMicrousd')::numeric) then raise exception 'listing_budget_integer_required'; end if;
  if coalesce(length(p_payload->>'runtimeCapability'),0) not between 32 and 512 or nullif(p_payload->>'launchNonce','') is null then raise exception 'listing_launch_identity_required'; end if;
  perform 1 from public.businesses where id=p_business_id for update;
  select * into strict a from public.artifacts where id=(p_payload->>'sourceArtifactId')::uuid and business_id=p_business_id and artifact_type='product.package.v1';
  if a.content->>'listingInputEnvelope' is distinct from p_payload->>'sourceEnvelope' or p_payload->>'sourceEnvelope' is null then raise exception 'listing_source_envelope_mismatch'; end if;
  perform private.stage17_assert_sources(p_business_id,a.id,p_payload->>'sourceContentHash',p_payload->'input',p_payload->>'inputHash');
  catalog:=private.stage17_assert_catalog(p_payload->>'knowledgeHash',p_payload->'workerHashes');
  perform private.stage17_assert_quote(p_payload->'quote',p_payload->>'inputHash',(p_payload->>'maximumMicrousd')::bigint);
  select * into r from public.listing_runs where business_id=p_business_id and source_artifact_id=a.id and input_hash=p_payload->>'inputHash';
  if r.id is not null then return jsonb_build_object('id',r.id,'runId',r.id,'workflowRunId',r.workflow_run_id,'outputArtifactId',r.output_artifact_id,'shouldStart',false); end if;
  select d.* into strict workflow from public.workflow_definitions d join public.packs p on p.id=d.pack_id where p.pack_key='workflow.etsy-listing-review' and p.version='1.0.0' and p.status<>'retired' and d.workflow_key='etsy.listing-review' and d.version='1.0.0' and d.status<>'retired';
  insert into public.workflow_runs(id,business_id,goal_id,workflow_definition_id,status,current_stage_key,idempotency_key,input,state,runtime_provider,runtime_launch_status,runtime_launch_nonce,runtime_launch_reserved_at)
   values(workflow_id,p_business_id,(p_payload->'input'->'product'->>'goalId')::uuid,workflow.id,'queued','specialist','listing:'||run_id,jsonb_build_object('listingRunId',run_id,'sourceArtifactId',a.id,'inputHash',p_payload->>'inputHash'),'{"publicationAllowed":false,"draftCreationAllowed":false}','vercel_workflow','reserved',(p_payload->>'launchNonce')::uuid,clock_timestamp());
  insert into public.listing_runs(id,business_id,owner_id,workflow_run_id,source_artifact_id,output_artifact_id,input,input_hash,source_content_hash,knowledge_hash,worker_hashes,catalog_snapshot,quote,maximum_microusd,capability_expires_at)
   values(run_id,p_business_id,auth.uid(),workflow_id,a.id,output_id,p_payload->'input',p_payload->>'inputHash',p_payload->>'sourceContentHash',p_payload->>'knowledgeHash',p_payload->'workerHashes',catalog,p_payload->'quote',(p_payload->>'maximumMicrousd')::bigint,least(clock_timestamp()+interval '1 hour',(p_payload->'input'->'product'->>'expiresAt')::timestamptz));
  insert into private.listing_run_capabilities values(run_id,private.stage13_hash(p_payload->>'runtimeCapability'),(p_payload->>'launchNonce')::uuid);
  foreach role_name in array array['specialist','reviewer'] loop
   n:=n+1; insert into public.workflow_stage_runs(id,business_id,workflow_run_id,stage_key,sequence,attempt,status,input) values(private.stage4_deterministic_uuid('listing:stage:'||run_id||':'||role_name),p_business_id,workflow_id,role_name,n,1,'pending',jsonb_build_object('listingRunId',run_id,'inputHash',p_payload->>'inputHash'));
  end loop;
  insert into public.events(business_id,workflow_run_id,event_type,actor_type,actor_id,payload) values(p_business_id,workflow_id,'listing.queued','owner',auth.uid()::text,jsonb_build_object('listingRunId',run_id,'sourceArtifactId',a.id,'maximumMicrousd',(p_payload->>'maximumMicrousd')::bigint,'publicationAllowed',false));
  return jsonb_build_object('id',run_id,'runId',run_id,'workflowRunId',workflow_id,'outputArtifactId',output_id,'shouldStart',true);
 end if;
 select * into strict r from public.listing_runs where id=(p_payload->>'runId')::uuid and business_id=p_business_id for update;
 if p_operation in ('cancel','close') then
  if p_operation='close' and r.capability_expires_at>clock_timestamp() then raise exception 'listing_run_not_expired'; end if;
  perform private.stage17_close(r.id,'cancelled',case p_operation when 'close' then 'expired' else 'owner_cancel' end);
 elsif p_operation='fail_launch' then
  if not exists(select 1 from private.listing_run_capabilities where listing_run_id=r.id and launch_nonce=(p_payload->>'launchNonce')::uuid) then raise exception 'listing_launch_nonce_mismatch' using errcode='42501'; end if;
  if r.status='queued' then perform private.stage17_close(r.id,'failed','launch_failed'); end if;
 else raise exception 'listing_owner_operation_invalid'; end if;
 return jsonb_build_object('id',r.id,'status',(select status from public.listing_runs where id=r.id),'costs',private.stage17_costs(r.id));
end $$;
create function public.listing_owner_transition(p_business_id uuid,p_operation text,p_payload jsonb default '{}',p_server_key text default '') returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if not private.is_business_owner(p_business_id) then raise exception 'owner_required' using errcode='42501'; end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>300000 then raise exception 'listing_request_invalid'; end if;
 insert into private.listing_mutation_admissions values(txid_current());
 result:=private.stage17_owner(p_business_id,p_operation,p_payload,p_server_key);
 delete from private.listing_mutation_admissions where transaction_id=txid_current();
 return result;
end $$;

create function private.stage17_assert_output(p_input jsonb,p_role text,p_output jsonb) returns void language plpgsql set search_path='' as $$
declare k text; c jsonb; ids jsonb; verdict text; statuses text[]; max_length integer;
begin
 if jsonb_typeof(p_output) is distinct from 'object' or p_output->>'version' is distinct from '1.0.0' then raise exception 'listing_output_invalid'; end if;
 if p_role='reviewer' then
  if p_output-array['version','verdict','checks']<>'{}' or jsonb_typeof(p_output->'checks') is distinct from 'object' or (p_output->'checks')-array['title','description','tags','attributes','imageOrder','disclosures','factualClaims']<>'{}' then raise exception 'listing_review_shape_invalid'; end if;
  foreach k in array array['title','description','tags','attributes','imageOrder','disclosures','factualClaims'] loop
   c:=p_output->'checks'->k;
   if c is null or c-array['status','rationale']<>'{}' or coalesce(c->>'status','') not in ('passed','failed','needs_evidence') or coalesce(length(btrim(c->>'rationale')),0) not between 30 and 400 or c->>'rationale' ~ '[[:cntrl:]]' then raise exception 'listing_review_check_invalid'; end if;
   statuses:=array_append(statuses,c->>'status');
  end loop;
  verdict:=case when 'failed'=any(statuses) then 'REJECT' when 'needs_evidence'=any(statuses) then 'NEEDS_EVIDENCE' else 'APPROVE' end;
  if p_output->>'verdict' is distinct from verdict then raise exception 'listing_review_verdict_mismatch'; end if;
 else
  if p_output-array['version','title','description','tags','attributes','imageOrder','disclosureKeys']<>'{}'
   or p_output->'attributes' is distinct from jsonb_build_object('taxonomyId',p_input->'product'->'taxonomyId','materials',p_input->'product'->'materials','properties',p_input->'product'->'properties')
   or p_output->'disclosureKeys' is distinct from (select jsonb_agg(x->'key' order by ord) from jsonb_array_elements(p_input->'disclosures') with ordinality t(x,ord))
   or jsonb_typeof(p_output->'description') is distinct from 'array' or jsonb_array_length(p_output->'description') not between 1 and 8
   or jsonb_typeof(p_output->'tags') is distinct from 'array' or jsonb_array_length(p_output->'tags') not between 1 and 13
   or jsonb_typeof(p_output->'imageOrder') is distinct from 'array' or jsonb_array_length(p_output->'imageOrder')<>jsonb_array_length(p_input->'product'->'images')
   or (select count(*)<>count(distinct x) from jsonb_array_elements_text(p_output->'imageOrder') x)
   or exists(select 1 from jsonb_array_elements_text(p_output->'imageOrder') x where not exists(select 1 from jsonb_array_elements(p_input->'product'->'images') y where y->>'assetId'=x))
   then raise exception 'listing_proposal_frozen_or_shape_invalid'; end if;
  if (select count(*)<>count(distinct lower(x->>'text')) from jsonb_array_elements(p_output->'tags') x) then raise exception 'listing_duplicate_tags'; end if;
  foreach k in array array['title','description','tags'] loop
   max_length:=case k when 'title' then 140 when 'tags' then 20 else 900 end;
   for c in select value from jsonb_array_elements(case k when 'title' then jsonb_build_array(p_output->'title') else p_output->k end) loop
    if jsonb_typeof(c) is distinct from 'object' or c-array['text','factIds']<>'{}' or coalesce(length(btrim(c->>'text')),0) not between 1 and max_length or c->>'text' is distinct from btrim(c->>'text') or c->>'text' ~ '[[:cntrl:]]'
     or jsonb_typeof(c->'factIds') is distinct from 'array' or jsonb_array_length(c->'factIds') not between 1 and 8
     or (select count(*)<>count(distinct x) from jsonb_array_elements_text(c->'factIds') x)
     or exists(select 1 from jsonb_array_elements_text(c->'factIds') x where not exists(select 1 from jsonb_array_elements(p_input->'facts') y where y->>'id'=x)) then raise exception 'listing_copy_fact_binding_invalid'; end if;
   end loop;
  end loop;
  if p_input->>'productType'='personalized' and not exists(select 1 from jsonb_array_elements(p_input->'imagery') x where x->>'assetId'=p_output->'imageOrder'->>0 and x->>'kind'='finished_product_photo') then raise exception 'listing_personalized_lead_photo_required'; end if;
 end if;
end $$;
create function private.stage17_runtime(p_run_id uuid,p_business_id uuid,p_operation text,p_payload jsonb) returns jsonb language plpgsql set search_path='' as $$
declare r public.listing_runs%rowtype; w public.workflow_runs%rowtype; reservation public.listing_cost_reservations%rowtype; settlement public.listing_cost_settlements%rowtype; prior public.listing_phase_outputs%rowtype;
 role_name text:=p_payload->>'role'; model text; task_id uuid; worker_id uuid; stage_id uuid; artifact_id uuid; knowledge_id uuid; worker_definition uuid;
 amount bigint; committed bigint; estimate jsonb; price jsonb; receipt jsonb; output jsonb; execution jsonb; context jsonb; tc jsonb; catalog jsonb; product jsonb; reviewed jsonb; proposal jsonb; review jsonb; specialist_execution jsonb; reviewer_execution jsonb;
 k text; item jsonb; input_ids uuid[]; rendered_description text;
begin
 select * into strict r from public.listing_runs where id=p_run_id and business_id=p_business_id for update;
 select * into strict w from public.workflow_runs where id=r.workflow_run_id and business_id=r.business_id for update;
 if p_operation='fail' then
  if coalesce(length(btrim(p_payload->>'reason')),0) not between 3 and 1500 then raise exception 'listing_failure_reason_required'; end if;
  perform private.stage17_close(r.id,'failed',p_payload->>'reason'); return jsonb_build_object('status',(select status from public.listing_runs where id=r.id),'costs',private.stage17_costs(r.id));
 end if;
 if coalesce(role_name,'') in ('specialist','reviewer') then
  model:=case role_name when 'specialist' then 'openai/gpt-5.6-luna' else 'anthropic/claude-haiku-4.5' end;
  task_id:=private.stage4_deterministic_uuid('listing:task:'||r.id||':'||role_name);
  worker_id:=private.stage4_deterministic_uuid('listing:worker:'||r.id||':'||role_name);
  stage_id:=private.stage4_deterministic_uuid('listing:stage:'||r.id||':'||role_name);
  artifact_id:=private.stage4_deterministic_uuid('listing:output:'||r.id||':'||role_name);
  knowledge_id:=private.stage4_deterministic_uuid('listing:knowledge:'||task_id);
  select * into reservation from public.listing_cost_reservations where listing_run_id=r.id and role=role_name;
  select * into settlement from public.listing_cost_settlements where listing_run_id=r.id and role=role_name;
  select * into prior from public.listing_phase_outputs where listing_run_id=r.id and role=role_name;
 elsif p_operation in ('reserve','settle','persist') then raise exception 'listing_role_invalid'; end if;
 -- Recording a dispatched request remains possible after cancellation, failure or
 -- expiry. It cannot issue another call, erase uncertainty or revive the run.
 if p_operation='settle' then
  receipt:=p_payload->'receipt';
  if reservation.listing_run_id is null then raise exception 'listing_call_not_reserved'; end if;
  if settlement.listing_run_id is not null then
   if settlement.reported_microusd is distinct from (p_payload->>'reportedMicrousd')::bigint or settlement.provider_request_id is distinct from p_payload->>'providerRequestId' or settlement.receipt is distinct from receipt then raise exception 'listing_settlement_replay_mismatch'; end if;
   return jsonb_build_object('recorded',false,'costs',private.stage17_costs(r.id));
  end if;
  if jsonb_typeof(receipt) is distinct from 'object' or receipt->>'version' is distinct from '1.0.0' or receipt->>'role' is distinct from role_name or receipt->>'executionMode' is distinct from 'listing.model' or receipt->'mockProvider' is distinct from 'false'::jsonb or receipt->>'requestedModel' is distinct from model
   or receipt->>'requestHash' is distinct from reservation.request_hash or receipt->>'transportRequestHash' is distinct from reservation.estimate->>'transportRequestHash'
   or receipt->>'providerRequestId' is distinct from p_payload->>'providerRequestId' or receipt->'reportedMicrousd' is distinct from p_payload->'reportedMicrousd'
   or receipt->'unknownCharge' is distinct from to_jsonb(p_payload->>'reportedMicrousd' is null) or jsonb_typeof(receipt->'outputValidated') is distinct from 'boolean' or coalesce(receipt->>'providerRequestId','') ~ '^(synthetic:|simulation:|fixture:|mock:)'
   or (p_payload->'reportedMicrousd' is distinct from 'null'::jsonb and (jsonb_typeof(p_payload->'reportedMicrousd') is distinct from 'number' or (p_payload->>'reportedMicrousd')::numeric<0 or (p_payload->>'reportedMicrousd')::numeric<>trunc((p_payload->>'reportedMicrousd')::numeric)))
   or (receipt->'outputValidated'='true'::jsonb and (receipt->>'actualProviderModelId' is distinct from model or (receipt->>'finishReason' is not null and receipt->>'finishReason'<>'stop') or receipt->>'provider' is distinct from 'openrouter' or (receipt->>'upstreamProvider' is not null and receipt->>'upstreamProvider'<>all(case role_name when 'specialist' then array['openai','OpenAI'] else array['anthropic','Anthropic'] end)) or coalesce(receipt->>'outputHash','') !~ '^[a-f0-9]{64}$' or nullif(p_payload->>'providerRequestId','') is null)) then raise exception 'listing_receipt_mismatch'; end if;
  insert into public.listing_cost_settlements(listing_run_id,business_id,role,reported_microusd,provider_request_id,receipt) values(r.id,r.business_id,role_name,(p_payload->>'reportedMicrousd')::bigint,p_payload->>'providerRequestId',receipt);
  update public.worker_runs set execution_metadata=execution_metadata||jsonb_build_object('receipt',receipt,'reportedMicrousd',p_payload->'reportedMicrousd') where id=worker_id;
  insert into public.events(business_id,workflow_run_id,event_type,actor_type,payload) values(r.business_id,r.workflow_run_id,'listing.cost_settled','system',jsonb_build_object('listingRunId',r.id,'role',role_name,'reportedMicrousd',p_payload->'reportedMicrousd','unknown',p_payload->'reportedMicrousd'='null'::jsonb));
  if p_payload->'reportedMicrousd'='null'::jsonb then perform private.stage17_close(r.id,'failed','provider_cost_unknown');
  elsif (private.stage17_costs(r.id)->>'committedMicrousd')::bigint>r.maximum_microusd then perform private.stage17_close(r.id,'failed','actual_cost_exceeded_approval');
  elsif receipt->'outputValidated' is distinct from 'true'::jsonb then perform private.stage17_close(r.id,'failed','provider_output_invalid'); end if;
  return jsonb_build_object('recorded',true,'costs',private.stage17_costs(r.id));
 end if;
 if r.capability_expires_at<=clock_timestamp() then raise exception 'listing_capability_expired' using errcode='42501'; end if;
 if p_operation='load' and r.status in ('completed','rejected','needs_evidence','failed','cancelled') then return private.stage17_view(r.id); end if;
 if r.status not in ('queued','running') then raise exception 'listing_run_terminal'; end if;
 perform private.stage17_assert_sources(r.business_id,r.source_artifact_id,r.source_content_hash,r.input,r.input_hash);
 catalog:=private.stage17_assert_catalog(r.knowledge_hash,r.worker_hashes);
 if catalog is distinct from r.catalog_snapshot then raise exception 'listing_qualification_snapshot_changed'; end if;
 if p_operation in ('load','guard') then
  if p_payload ? 'runtimeRunId' then
   if coalesce(length(p_payload->>'runtimeRunId'),0) not between 1 and 300 or (w.runtime_run_id is not null and w.runtime_run_id is distinct from p_payload->>'runtimeRunId') then raise exception 'listing_runtime_identity_mismatch'; end if;
   update public.workflow_runs set runtime_run_id=p_payload->>'runtimeRunId',runtime_launch_status='started',status='running',started_at=coalesce(started_at,clock_timestamp()) where id=w.id;
   update public.listing_runs set status='running' where id=r.id;
  end if;
  return private.stage17_view(r.id);
 end if;
 if p_operation='reserve' then
  if reservation.listing_run_id is not null then
   if reservation.request_hash is distinct from p_payload->>'requestHash' or reservation.reserved_microusd is distinct from (p_payload->>'reservedMicrousd')::bigint or reservation.estimate is distinct from p_payload->'estimate' or reservation.context is distinct from p_payload->'context' then raise exception 'listing_reservation_replay_mismatch'; end if;
   return jsonb_build_object('shouldExecute',false,'committedMicrousd',(private.stage17_costs(r.id)->>'committedMicrousd')::bigint);
  end if;
  if r.phase<>role_name or r.capability_expires_at<=clock_timestamp()+interval '5 minutes' then raise exception 'listing_phase_or_lifetime_invalid'; end if;
  if role_name='reviewer' and not exists(select 1 from public.listing_phase_outputs o join public.listing_cost_settlements s using(listing_run_id,role,business_id) where o.listing_run_id=r.id and o.role='specialist' and s.reported_microusd is not null and s.receipt->'outputValidated'='true'::jsonb) then raise exception 'listing_specialist_settlement_required'; end if;
  if exists(select 1 from public.listing_cost_reservations x left join public.listing_cost_settlements s using(listing_run_id,role,business_id) where x.listing_run_id=r.id and s.reported_microusd is null) then raise exception 'listing_prior_cost_unresolved'; end if;
  amount:=(p_payload->>'reservedMicrousd')::bigint; estimate:=p_payload->'estimate'; price:=estimate->'quote'; context:=p_payload->'context'; tc:=context->'taskContract';
  if jsonb_typeof(p_payload->'reservedMicrousd') is distinct from 'number' or (p_payload->>'reservedMicrousd')::numeric<>trunc((p_payload->>'reservedMicrousd')::numeric) or amount not between 0 and r.maximum_microusd or amount>(r.quote->'ceilings'->>role_name)::bigint
   or coalesce(p_payload->>'requestHash','') !~ '^[a-f0-9]{64}$' or estimate->>'version' is distinct from 'listing-estimate-1.0' or estimate->>'role' is distinct from role_name
   or estimate->>'inputHash' is distinct from r.input_hash or (estimate->>'maximumMicrousd')::bigint is distinct from r.maximum_microusd or (estimate->>'reservedMicrousd')::bigint is distinct from amount
   or (estimate->>'approvedPhaseCeilingMicrousd')::bigint is distinct from (r.quote->'ceilings'->>role_name)::bigint or coalesce(estimate->>'transportRequestHash','') !~ '^[a-f0-9]{64}$'
   or estimate->'primaryOnly' is distinct from 'true'::jsonb or estimate->'estimateOnly' is distinct from 'true'::jsonb or estimate->'providerInvoiceGuarantee' is distinct from 'false'::jsonb
   or coalesce((estimate->>'requestBytes')::integer,0) not between 1 and 64000 or (estimate->>'inputTokenAllowance')::integer is distinct from (estimate->>'requestBytes')::integer+8192 or estimate->'outputTokenAllowance' is distinct from '6000'::jsonb
   or price->>'modelId' is distinct from model or price->>'source' is distinct from 'https://openrouter.ai/api/v1/models'
   or coalesce((price->>'verifiedAt')::timestamptz,'-infinity')<=clock_timestamp()-interval '5 minutes' or (price->>'verifiedAt')::timestamptz>clock_timestamp()+interval '5 seconds' then raise exception 'listing_reservation_estimate_invalid'; end if;
  foreach k in array array['inputPerMillion','outputPerMillion','cacheWritePerMillion'] loop
   if jsonb_typeof(price->k) is distinct from 'number' or (price->>k)::numeric not between 0 and 1000000 then raise exception 'listing_price_invalid'; end if;
  end loop;
  if amount<>ceil((estimate->>'inputTokenAllowance')::numeric*((price->>'inputPerMillion')::numeric+(price->>'cacheWritePerMillion')::numeric)+6000*(price->>'outputPerMillion')::numeric)
   or ceil(72192*((price->>'inputPerMillion')::numeric+(price->>'cacheWritePerMillion')::numeric)+6000*(price->>'outputPerMillion')::numeric)>(r.quote->'ceilings'->>role_name)::bigint then raise exception 'listing_price_exceeds_quote'; end if;
  committed:=(private.stage17_costs(r.id)->>'committedMicrousd')::bigint;
  if committed+amount>r.maximum_microusd then raise exception 'listing_budget_exceeded'; end if;
  if jsonb_typeof(context) is distinct from 'object' or tc->>'id' is distinct from task_id::text or tc->'permittedCapabilities' is distinct from '[]'::jsonb
   or tc->'requiredKnowledge' is distinct from '["etsy.listing-review"]'::jsonb or tc->'escalationRules'->'maximumAttempts' is distinct from '1'::jsonb or tc->'escalationRules'->'retry' is distinct from 'false'::jsonb
   or tc->'inputArtifactIds' is distinct from jsonb_build_array(r.source_artifact_id,knowledge_id)
   or jsonb_array_length(context->'inputArtifacts')<>2 or context->'inputArtifacts'->0->>'id' is distinct from r.source_artifact_id::text
   or context->'inputArtifacts'->0->'content'->'input' is distinct from r.input or context->'inputArtifacts'->1->>'id' is distinct from knowledge_id::text
   or context->'inputArtifacts'->1->'content' is distinct from catalog->'knowledge'->'content' then raise exception 'listing_task_context_mismatch'; end if;
  if role_name='reviewer' and (context->'inputArtifacts'->0->'content'->'proposal' is distinct from (select o.output from public.listing_phase_outputs o where listing_run_id=r.id and role='specialist') or context->'inputArtifacts'->0->'content'->'specialistExecution' is distinct from (select o.execution from public.listing_phase_outputs o where listing_run_id=r.id and role='specialist')) then raise exception 'listing_reviewer_context_mismatch'; end if;
  worker_definition:=(catalog->role_name->>'workerDefinitionId')::uuid;
  insert into public.artifacts(id,business_id,workflow_run_id,artifact_type,name,content,checksum,metadata) values(knowledge_id,r.business_id,r.workflow_run_id,'pack.knowledge','Pinned listing review policy',catalog->'knowledge'->'content',private.stage14_hash(catalog->'knowledge'->'content'),jsonb_build_object('knowledgeHash',r.knowledge_hash,'knowledgeKey','etsy.listing-review','knowledgeVersion','1.0.0'));
  insert into public.task_contracts(id,business_id,workflow_run_id,workflow_stage_run_id,worker_definition_id,status,objective,input_artifact_ids,permitted_capabilities,required_knowledge,required_output_schema,completion_criteria,failure_criteria,non_goals,escalation_rules)
   values(task_id,r.business_id,r.workflow_run_id,stage_id,worker_definition,'running',tc->>'objective',array[r.source_artifact_id,knowledge_id],'{}',array['etsy.listing-review'],tc->'requiredOutputSchema',tc->'completionCriteria',tc->'failureCriteria',array(select jsonb_array_elements_text(tc->'nonGoals')),tc->'escalationRules');
  insert into public.worker_runs(id,business_id,workflow_run_id,task_contract_id,worker_definition_id,status,input,execution_metadata,started_at) values(worker_id,r.business_id,r.workflow_run_id,task_id,worker_definition,'running',context,jsonb_build_object('provider','openrouter','model',model,'requestHash',p_payload->>'requestHash','maximumAttempts',1,'primaryOnly',true),clock_timestamp());
  insert into public.listing_cost_reservations(listing_run_id,business_id,role,reserved_microusd,request_hash,model,provider,estimate,context,task_contract_id,worker_run_id) values(r.id,r.business_id,role_name,amount,p_payload->>'requestHash',model,'openrouter',estimate,context,task_id,worker_id);
  update public.workflow_stage_runs set status='running',started_at=clock_timestamp() where id=stage_id;
  update public.workflow_runs set status='running',started_at=coalesce(started_at,clock_timestamp()),current_stage_key=role_name where id=r.workflow_run_id;
  update public.listing_runs set status='running' where id=r.id;
  insert into public.events(business_id,workflow_run_id,event_type,actor_type,payload) values(r.business_id,r.workflow_run_id,'listing.call_reserved','system',jsonb_build_object('listingRunId',r.id,'role',role_name,'taskId',task_id,'reservedMicrousd',amount,'requestHash',p_payload->>'requestHash'));
  return jsonb_build_object('shouldExecute',true,'committedMicrousd',committed+amount);
 end if;
 if p_operation='persist' then
  output:=p_payload->'output'; execution:=p_payload->'execution';
  if prior.listing_run_id is not null then
   if prior.output is distinct from output or prior.execution is distinct from execution then raise exception 'listing_output_replay_mismatch'; end if;
   return private.stage17_view(r.id);
  end if;
  if r.phase<>role_name or settlement.listing_run_id is null or settlement.reported_microusd is null or settlement.receipt->'outputValidated' is distinct from 'true'::jsonb
   or reservation.request_hash is distinct from execution->>'requestHash' or settlement.provider_request_id is distinct from execution->>'providerRequestId'
   or settlement.receipt->>'outputHash' is distinct from private.stage14_hash(output) or execution->>'outputHash' is distinct from private.stage14_hash(output)
   or execution-array['version','mode','taskId','workerKey','workerVersion','providerModelId','providerRequestId','requestHash','outputHash','completedAt']<>'{}' or execution->>'version' is distinct from '1.0.0' or execution->>'mode' is distinct from 'live_model' or execution->>'taskId' is distinct from task_id::text
   or execution->>'workerKey' is distinct from 'listing.'||role_name or execution->>'workerVersion' is distinct from '1.0.0' or execution->>'providerModelId' is distinct from model
   or execution->>'completedAt' is distinct from settlement.receipt->>'completedAt' or coalesce((execution->>'completedAt')::timestamptz,'-infinity')<reservation.created_at or (execution->>'completedAt')::timestamptz>clock_timestamp()
   or (private.stage17_costs(r.id)->>'committedMicrousd')::bigint>r.maximum_microusd then raise exception 'listing_validated_known_settlement_required'; end if;
  perform private.stage17_assert_output(r.input,role_name,output);
  if role_name='reviewer' then
   select o.execution into strict specialist_execution from public.listing_phase_outputs o where listing_run_id=r.id and role='specialist';
   if specialist_execution->>'providerModelId'=execution->>'providerModelId' or specialist_execution->>'providerRequestId'=execution->>'providerRequestId' or specialist_execution->>'taskId'=execution->>'taskId' or (specialist_execution->>'completedAt')::timestamptz>(execution->>'completedAt')::timestamptz then raise exception 'listing_independent_review_required'; end if;
  end if;
  insert into public.artifacts(id,business_id,workflow_run_id,task_contract_id,artifact_type,name,content,checksum,metadata) values(artifact_id,r.business_id,r.workflow_run_id,task_id,'listing.'||role_name||'.v1','Validated listing '||role_name,output,private.stage14_hash(output),jsonb_build_object('listingRunId',r.id,'execution',execution));
  insert into public.listing_phase_outputs(listing_run_id,business_id,workflow_run_id,role,artifact_id,output,output_hash,execution) values(r.id,r.business_id,r.workflow_run_id,role_name,artifact_id,output,private.stage14_hash(output),execution);
  update public.task_contracts set status='completed' where id=task_id;
  update public.worker_runs set status='completed',output=p_payload->'output',execution_metadata=execution_metadata||jsonb_build_object('execution',execution),completed_at=clock_timestamp() where id=worker_id;
  update public.workflow_stage_runs set status='completed',output=jsonb_build_object('artifactId',artifact_id,'outputHash',private.stage14_hash(p_payload->'output')),completed_at=clock_timestamp() where id=stage_id;
  update public.listing_runs set phase=case role_name when 'specialist' then 'reviewer' else 'issue' end where id=r.id;
  update public.workflow_runs set current_stage_key=case role_name when 'specialist' then 'reviewer' else 'issue' end where id=r.workflow_run_id;
  insert into public.events(business_id,workflow_run_id,event_type,actor_type,payload) values(r.business_id,r.workflow_run_id,'listing.output_persisted','system',jsonb_build_object('listingRunId',r.id,'role',role_name,'artifactId',artifact_id,'outputHash',private.stage14_hash(output)));
  if role_name='reviewer' and output->>'verdict'<>'APPROVE' then
   update public.workflow_runs set state=state||jsonb_build_object('reviewVerdict',output->>'verdict') where id=r.workflow_run_id;
   perform private.stage17_close(r.id,case output->>'verdict' when 'REJECT' then 'rejected' else 'needs_evidence' end,'review_'||lower(output->>'verdict'));
  end if;
  return private.stage17_view(r.id);
 end if;
 if p_operation='finish' then
  if r.phase<>'issue' or (select count(*) from public.listing_phase_outputs where listing_run_id=r.id)<>2 or (select count(*) from public.listing_cost_settlements cs where cs.listing_run_id=r.id and cs.reported_microusd is not null and cs.receipt->'outputValidated'='true'::jsonb)<>2
   or (private.stage17_costs(r.id)->>'committedMicrousd')::bigint>r.maximum_microusd then raise exception 'listing_finish_two_known_calls_required'; end if;
  select o.output,o.execution into strict proposal,specialist_execution from public.listing_phase_outputs o where listing_run_id=r.id and role='specialist';
  select o.output,o.execution into strict review,reviewer_execution from public.listing_phase_outputs o where listing_run_id=r.id and role='reviewer';
  perform private.stage17_assert_output(r.input,'specialist',proposal); perform private.stage17_assert_output(r.input,'reviewer',review);
  if review->>'verdict' is distinct from 'APPROVE' or specialist_execution->>'providerModelId'=reviewer_execution->>'providerModelId' or specialist_execution->>'providerRequestId'=reviewer_execution->>'providerRequestId' or specialist_execution->>'taskId'=reviewer_execution->>'taskId' then raise exception 'listing_approved_independent_review_required'; end if;
  product:=p_payload->'product'; reviewed:=p_payload->'reviewedListing';
  select string_agg(x->>'text',E'\n\n' order by ord) into rendered_description from jsonb_array_elements((proposal->'description')||(r.input->'disclosures')) with ordinality t(x,ord);
  if product->>'id' is distinct from r.output_artifact_id::text or product-array['id','title','description','tags','images'] is distinct from (r.input->'product')-array['id','title','description','tags','images']
   or product->>'title' is distinct from proposal->'title'->>'text' or product->>'description' is distinct from rendered_description
   or product->'tags' is distinct from (select jsonb_agg(x->'text' order by ord) from jsonb_array_elements(proposal->'tags') with ordinality t(x,ord))
   or product->'images' is distinct from (select jsonb_agg(image order by ord) from jsonb_array_elements_text(proposal->'imageOrder') with ordinality o(id,ord) join lateral jsonb_array_elements(r.input->'product'->'images') image on image->>'assetId'=o.id)
   then raise exception 'listing_final_package_changed'; end if;
  if reviewed->>'version' is distinct from '1.0.0' or reviewed->'input' is distinct from r.input or reviewed->'proposal' is distinct from proposal or reviewed->'review' is distinct from review
   or reviewed->'specialist' is distinct from specialist_execution or reviewed->'reviewer' is distinct from reviewer_execution or reviewed->>'knowledgeHash' is distinct from r.knowledge_hash
   or reviewed->>'outputArtifactId' is distinct from r.output_artifact_id::text or reviewed->>'productPackageHash' is distinct from private.stage14_hash(product) or reviewed->'publicationAllowed' is distinct from 'false'::jsonb
   or coalesce(length(p_payload->>'etsyDraftEnvelope'),0) not between 32 and 200000 or coalesce(length(p_payload->>'listingReviewEnvelope'),0) not between 32 and 300000 then raise exception 'listing_final_review_binding_invalid'; end if;
  perform private.stage16_assert_package(r.business_id,product);
  insert into public.artifacts(id,business_id,workflow_run_id,artifact_type,name,content,checksum,metadata)
   values(r.output_artifact_id,r.business_id,r.workflow_run_id,'product.package.v1',product->>'title',jsonb_build_object('product',product,'reviewedListing',reviewed,'etsyDraftEnvelope',p_payload->>'etsyDraftEnvelope','listingReviewEnvelope',p_payload->>'listingReviewEnvelope'),private.stage14_hash(product),jsonb_build_object('listingRunId',r.id,'sourceArtifactId',r.source_artifact_id,'inputHash',r.input_hash,'publicationAllowed',false));
  update public.workflow_runs set state=state||jsonb_build_object('outputArtifactId',r.output_artifact_id,'productPackageHash',private.stage14_hash(product),'reviewVerdict','APPROVE','publicationAllowed',false,'draftCreationAllowed',false) where id=r.workflow_run_id;
  perform private.stage17_close(r.id,'completed','reviewed_listing_issued');
  return private.stage17_view(r.id);
 end if;
 raise exception 'listing_runtime_operation_invalid';
end $$;
create function public.listing_runtime_transition(p_run_id uuid,p_business_id uuid,p_runtime_capability text,p_operation text,p_payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if coalesce(length(p_runtime_capability),0) not between 32 and 512 or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>900000 then raise exception 'listing_runtime_request_invalid' using errcode='42501'; end if;
 if not exists(select 1 from public.listing_runs r join private.listing_run_capabilities c on c.listing_run_id=r.id where r.id=p_run_id and r.business_id=p_business_id and c.capability_hash=private.stage13_hash(p_runtime_capability)) then raise exception 'listing_capability_denied' using errcode='42501'; end if;
 insert into private.listing_mutation_admissions values(txid_current());
 result:=private.stage17_runtime(p_run_id,p_business_id,p_operation,p_payload);
 delete from private.listing_mutation_admissions where transaction_id=txid_current();
 return result;
end $$;

revoke all on function public.listing_owner_transition(uuid,text,jsonb,text),public.listing_runtime_transition(uuid,uuid,text,text,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.listing_owner_transition(uuid,text,jsonb,text) to authenticated;
grant execute on function public.listing_runtime_transition(uuid,uuid,text,text,jsonb) to anon,authenticated;
revoke all on function private.stage17_qualification_immutable(),private.stage17_qualified(),private.stage17_admitted(),private.stage17_record_guard(),private.stage17_core_guard(),private.stage17_costs(uuid),private.stage17_assert_sources(uuid,uuid,text,jsonb,text),private.stage17_assert_catalog(text,jsonb),private.stage17_assert_quote(jsonb,text,bigint),private.stage17_close(uuid,text,text),private.stage17_view(uuid),private.stage17_owner(uuid,text,jsonb,text),private.stage17_assert_output(jsonb,text,jsonb),private.stage17_runtime(uuid,uuid,text,jsonb) from public,anon,authenticated,service_role;

-- BEGIN TRUSTED QUALIFICATION RUNTIME
-- Stage17 qualification is an explicitly approved, bounded live-model evaluation.
-- Catalog examples are synthetic test inputs, never production source evidence.
create table private.listing_qualification_runs (
 id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id), owner_id uuid not null references auth.users(id),
 workflow_run_id uuid not null unique, suite_hash text not null check(suite_hash ~ '^[a-f0-9]{64}$'),
 knowledge_hash text not null check(knowledge_hash ~ '^[a-f0-9]{64}$'), worker_hashes jsonb not null, catalog_snapshot jsonb not null,
 quote jsonb not null, maximum_microusd bigint not null check(maximum_microusd between 1 and 1000000),
 capability_hash text not null check(capability_hash ~ '^[a-f0-9]{64}$'), launch_nonce uuid not null,
 expires_at timestamptz not null, created_at timestamptz not null default clock_timestamp(),
 status text not null default 'queued' check(status in ('queued','running','completed','failed','cancelled')), reason text, completed_at timestamptz,
 foreign key(workflow_run_id,business_id) references public.workflow_runs(id,business_id), unique(id,business_id), unique(business_id,launch_nonce)
);
create table private.listing_qualification_reservations (
 run_id uuid not null references private.listing_qualification_runs(id), case_key text not null,
 role text not null check(role in ('specialist','reviewer')), reserved_microusd bigint not null check(reserved_microusd between 0 and 1000000),
 request_hash text not null check(request_hash ~ '^[a-f0-9]{64}$'), estimate jsonb not null, context jsonb not null,
 created_at timestamptz not null default clock_timestamp(), primary key(run_id,case_key)
);
create table private.listing_qualification_settlements (
 run_id uuid not null, case_key text not null, reported_microusd bigint check(reported_microusd between 0 and 9007199254740991),
 provider_request_id text check(length(provider_request_id) between 1 and 200), receipt jsonb not null,
 created_at timestamptz not null default clock_timestamp(), primary key(run_id,case_key),
 foreign key(run_id,case_key) references private.listing_qualification_reservations(run_id,case_key)
);
create table private.listing_qualification_outputs (
 run_id uuid not null, case_key text not null, output jsonb not null, execution jsonb not null, grade jsonb not null,
 created_at timestamptz not null default clock_timestamp(), primary key(run_id,case_key),
 foreign key(run_id,case_key) references private.listing_qualification_settlements(run_id,case_key)
);
alter table private.listing_live_qualifications add column qualification_run_id uuid references private.listing_qualification_runs(id);
create function private.stage17_qualification_guard() returns trigger language plpgsql set search_path='' as $$ begin
 if not private.stage17_admitted() then raise exception 'listing_qualification_runtime_managed' using errcode='42501'; end if;
 if tg_table_name='listing_qualification_runs' then
  if tg_op='DELETE' then raise exception 'listing_qualification_history_immutable'; end if;
  if tg_op='UPDATE' and to_jsonb(new)-array['status','reason','completed_at'] is distinct from to_jsonb(old)-array['status','reason','completed_at'] then raise exception 'listing_qualification_identity_immutable'; end if;
  if tg_op='UPDATE' and old.status in ('completed','failed','cancelled') and new is distinct from old then raise exception 'listing_qualification_terminal_immutable'; end if;
 elsif tg_op<>'INSERT' then raise exception 'listing_qualification_provenance_append_only'; end if;
 return new;
end $$;
do $$ declare n text; begin
 foreach n in array array['listing_qualification_runs','listing_qualification_reservations','listing_qualification_settlements','listing_qualification_outputs'] loop
  execute format('alter table private.%I enable row level security',n);
  execute format('revoke all on private.%I from public,anon,authenticated,service_role',n);
  execute format('create trigger %I before insert or update or delete on private.%I for each row execute function private.stage17_qualification_guard()',n||'_guard',n);
 end loop;
end $$;
create function private.stage17_qualification_costs(p_run uuid) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('knownMicrousd',coalesce(sum(s.reported_microusd),0),'reservedMicrousd',coalesce(sum(r.reserved_microusd),0),
 'committedMicrousd',coalesce(sum(coalesce(s.reported_microusd,r.reserved_microusd)),0),
 'unknownCount',count(*) filter(where s.run_id is not null and s.reported_microusd is null),'pendingCount',count(*) filter(where s.run_id is null))
 from private.listing_qualification_reservations r left join private.listing_qualification_settlements s using(run_id,case_key) where r.run_id=p_run;
$$;

create function private.stage17_qualification_catalog(p_knowledge_hash text,p_worker_hashes jsonb) returns jsonb language plpgsql set search_path='' as $$
declare role_name text; d public.worker_definitions%rowtype; p public.packs%rowtype; m jsonb; k jsonb; result jsonb:='{}'; expected_model text;
begin
 select p0.manifest->'knowledge'->0 into strict k from public.packs p0 join public.pack_knowledge_definitions kd on kd.pack_id=p0.id
  where p0.pack_key='knowledge.etsy-listing-review' and p0.version='1.0.0' and p0.status<>'retired' and kd.knowledge_key='etsy.listing-review' and kd.version='1.0.0'
   and kd.content=p0.manifest->'knowledge'->0->'content' and kd.verified_at=(p0.manifest->'knowledge'->0->>'verifiedAt')::timestamptz and kd.freshness_days=(p0.manifest->'knowledge'->0->>'freshnessDays')::integer;
 if private.stage14_hash(k) is distinct from p_knowledge_hash or (k->>'verifiedAt')::timestamptz>clock_timestamp() or (k->>'verifiedAt')::timestamptz+(k->>'freshnessDays')::integer*interval '1 day'<=clock_timestamp() then raise exception 'listing_knowledge_changed_or_stale'; end if;
 foreach role_name in array array['specialist','reviewer'] loop
  expected_model:=case role_name when 'specialist' then 'openai/gpt-5.6-luna' else 'anthropic/claude-haiku-4.5' end;
  select * into strict p from public.packs where pack_key='worker.listing-'||role_name and version='1.0.0' and status<>'retired';
  m:=p.manifest->'workers'->0->'manifest';
  select * into strict d from public.worker_definitions where pack_id=p.id and worker_key='listing.'||role_name and version='1.0.0';
  if private.stage14_hash(m) is distinct from p_worker_hashes->>role_name or d.input_schema is distinct from m->'inputSchema' or d.output_schema is distinct from m->'outputSchema'
   or d.model_requirements is distinct from m->'modelRequirements' or d.capability_requirements is distinct from m->'capabilityPolicy'->'allowed' or d.knowledge_requirements is distinct from m->'knowledgeRequirements'
   or d.charter is distinct from m->'worker'->>'charter' or d.role is distinct from m->'worker'->>'role'
   or m->'capabilityPolicy'->'allowed' is distinct from '[]'::jsonb or m->'modelRequirements'->'maximumAttempts' is distinct from '1'::jsonb
   or m->'modelRequirements'->'primaryOnly' is distinct from 'true'::jsonb or m->'modelRequirements'->>'qualificationScope' is distinct from 'stage17_listing_review'
   then raise exception 'listing_worker_source_changed'; end if;
  if not exists(select 1 from public.model_routes route join public.model_definitions model on model.id=route.primary_model_definition_id
   where route.route_key=d.model_requirements->>'routeKey' and model.provider='openrouter' and model.provider_model_id=expected_model and route.status='qualified' and model.status='qualified') then raise exception 'listing_primary_model_changed'; end if;
  result:=result||jsonb_build_object(role_name,jsonb_build_object('workerDefinitionId',d.id,'workerFingerprint',private.stage6_worker_fingerprint(d.id),'manifest',m,'pack',p.manifest));
 end loop;
 return result||jsonb_build_object('knowledge',k);
end $$;
create function private.stage17_qualification_close(p_run uuid,p_status text,p_reason text) returns void language plpgsql set search_path='' as $$
declare r private.listing_qualification_runs%rowtype;
begin
 select * into strict r from private.listing_qualification_runs where id=p_run for update;
 if r.status in ('completed','failed','cancelled') then return; end if;
 if p_status not in ('completed','failed','cancelled') then raise exception 'listing_qualification_status_invalid'; end if;
 update private.listing_qualification_runs set status=p_status,reason=left(p_reason,500),completed_at=clock_timestamp() where id=p_run;
 update public.workflow_runs set status=p_status,current_stage_key='terminal',completed_at=clock_timestamp(),state=state||jsonb_build_object('reason',left(p_reason,500),'costs',private.stage17_qualification_costs(p_run),'productionAllowed',false) where id=r.workflow_run_id;
 update public.workflow_stage_runs set status=case when status='running' then 'failed' else 'skipped' end,completed_at=clock_timestamp(),failure=jsonb_build_object('reason',left(p_reason,500)) where workflow_run_id=r.workflow_run_id and status in ('pending','running');
 insert into public.events(business_id,workflow_run_id,event_type,actor_type,payload) values(r.business_id,r.workflow_run_id,'listing.qualification.'||p_status,'system',jsonb_build_object('qualificationRunId',p_run,'reason',left(p_reason,500),'costs',private.stage17_qualification_costs(p_run),'productionAllowed',false));
end $$;
