otanical design.","factIds":["ai","design"]}],"imagery":[{"assetId":"11111111-1111-4111-8111-000000000011","sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","productFactsHash":"72c9b6c67eb9943eacf1ad20762f8681e21d55d93c23763b0edb489ef02a856c","kind":"finished_product_photo","finishedProductShown":true,"reviewArtifactId":"11111111-1111-4111-8111-000000000020","reviewedAt":"2026-10-01T10:00:00.000Z","altText":"Front of the natural cotton shirt with the botanical line drawing","reviewResultHash":"e81d090d927d7e5ad522c13aab654fddc1700f47540f1aeb0bbd7bd72438231a","reviewResult":{"businessId":"11111111-1111-4111-8111-000000000002","outcome":"PASS","productMatches":true,"finishedProductShown":true,"imageRightsVerified":true,"observedProduct":"Synthetic reviewed front photo: the complete natural short-sleeve shirt has the seller''s botanical line drawing printed on its front. Its garment color and design placement match the included product and creative snapshots; no blank placeholder or text overlay appears."}},{"assetId":"11111111-1111-4111-8111-000000000012","sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","productFactsHash":"72c9b6c67eb9943eacf1ad20762f8681e21d55d93c23763b0edb489ef02a856c","kind":"finished_product_mockup","finishedProductShown":true,"reviewArtifactId":"11111111-1111-4111-8111-000000000021","reviewedAt":"2026-10-01T10:00:00.000Z","altText":"Close view of the printed botanical drawing on the finished natural shirt","reviewResultHash":"dc2195200c6b494b1aed49f30be204c26729fac3f7113e7dec5f823bd76fadf4","reviewResult":{"businessId":"11111111-1111-4111-8111-000000000002","outcome":"PASS","productMatches":true,"finishedProductShown":true,"imageRightsVerified":true,"observedProduct":"Synthetic reviewed detail mockup: the botanical line drawing is printed on the same finished natural shirt, with the garment visibly surrounding the artwork. The front placement and natural garment color match the included snapshots; this is not a standalone raw-art PNG."}}]},"modelExecutionEvidence":{"evidenceMode":"synthetic","specialistActualModel":"fixture/producer-a","reviewerActualModel":"fixture/reviewer-b","qualificationScope":"stage17_listing_review"}},"expectedOutput":{"version":"1.0.0","title":{"text":"Botanical Cotton T-Shirt, Natural, Regular Fit","factIds":["product","design","material","color","fit"]},"description":[{"text":"A natural short-sleeve T-shirt featuring my original botanical line drawing printed on the front.","factIds":["product","color","design"]},{"text":"Made from 100% cotton with a regular fit. Available in sizes S, M and L.","factIds":["material","fit","sizes"]}],"tags":[{"text":"botanical shirt","factIds":["design","product"]},{"text":"cotton t shirt","factIds":["material","product"]},{"text":"natural color shirt","factIds":["color","product"]},{"text":"line drawing shirt","factIds":["design","product"]}],"attributes":{"taxonomyId":482,"materials":["cotton"],"properties":[{"propertyId":504,"valueIds":[505],"values":["Natural"],"scaleId":null}]},"imageOrder":["11111111-1111-4111-8111-000000000011","11111111-1111-4111-8111-000000000012"],"disclosureKeys":["production_partner","ai"]}},{"name":"description: grounded complete proposal","input":{"trainingOnly":true,"evaluatedAt":"2026-10-01T10:00:00.000Z","scope":"Offline synthetic teaching example; no execution or live qualification.","focusDimension":"description","lesson":"Explain the front design first, then 100% cotton, regular fit and actual S/M/L sizes. Cover customer-relevant facts and preserve disclosure assembly rather than inventing care advice.","listingInput":{"version":"1.0.0","evidenceMode":"synthetic","factsVerifiedAt":"2026-10-01T10:00:00.000Z","productType":"original_design_on_base_product","aiAssisted":true,"product":{"version":"1.0","id":"11111111-1111-4111-8111-000000000001","businessId":"11111111-1111-4111-8111-000000000002","goalId":"11111111-1111-4111-8111-000000000003","workflowRunId":"111